Classify this Express handler. Assume req.query.term is attacker-controlled and escapeHtml is defined exactly as shown.

function escapeHtml(value: string) {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}
const term = escapeHtml(String(req.query.term ?? ''));
res.type('html').send('<p>Search: ' + term + '</p>');

If vulnerable, return exactly: VERDICT: VULNERABLE; CWE: CWE-N
If safe, return exactly: VERDICT: SAFE

